Thread t = new Thread(() -> System.out.println("A"));
t.start();   // pide a la JVM un NUEVO thread, que ejecuta la tarea
// t.run();  // solo una llamada a método normal: sigue UN thread!
t.join();    // espera aquí hasta que t termine
System.out.println("B");   // siempre después de A

synchronized String take() throws InterruptedException {
    while (items.isEmpty()) {   // WHILE, nunca IF
        wait();
    }
    return items.removeFirst();
}

int old, next;
do {
    old = value.get();          // lee
    next = old + 1;             // calcula
} while (!value.compareAndSet(old, next)); // repite si cambió

async function sequential() {
	await sleep(300);
	await sleep(200);
	await sleep(100);          // total cerca de 600 ms
}
async function together() {
	await Promise.all([sleep(300), sleep(200), sleep(100)]); // cerca de 300 ms
}

